class MarketplaceDetailScreen extends ConsumerWidget {const MarketplaceDetailScreen({super.key,required this.listingId});final String listingId;@override Widget build(BuildContext c,WidgetRef r){return Scaffold(appBar:AppBar(title:const Text('Listing details')),body:r.watch(marketplaceDetailProvider(listingId)).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e')),data:(x)=>ListView(padding:const EdgeInsets.all(16),children:[SizedBox(height:220,child:x.photos.isEmpty?const ColoredBox(color:Color(0xffe8f5e9),child:Icon(Icons.pets,size:80)):Image.network(x.photos.first,fit:BoxFit.cover)),const SizedBox(height:16),Text(x.title,style:Theme.of(c).textTheme.headlineSmall),Text(NumberFormat.currency(locale:'en_IN',symbol:'₹',decimalDigits:0).format(x.price),style:Theme.of(c).textTheme.titleLarge),if(x.isNegotiable)const Text('Negotiable'),const Divider(),_row('Breed',x.breed),_row('Age',x.ageMonths==null?null:'${x.ageMonths} months'),_row('Weight',x.weightKg==null?null:'${x.weightKg} kg'),_row('Milk/day',x.milkYieldLitres==null?null:'${x.milkYieldLitres} L'),_row('Fat',x.fatPct==null?null:'${x.fatPct}%'),_row('Pregnancy',x.isPregnant?'${x.monthsPregnant} months pregnant':'Not pregnant'),_row('Location',[x.locationVillage,x.locationDistrict,x.locationState].whereType<String>().join(', ')),if(x.healthVerified)const Chip(label:Text('Health verified')),if(x.vaccinationVerified)const Chip(label:Text('Vaccination verified')),if(x.description!=null)Text(x.description!),const Divider(),Text('Seller: ${x.sellerName ?? 'Farmer'}'),ElevatedButton.icon(onPressed:() async {await r.read(dioProvider).post('/marketplace/listings/${x.id}/inquiries',data:{'message':'I am interested in this cattle.'});if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Inquiry sent')));},icon:const Icon(Icons.message),label:const Text('Send inquiry'))])));}_row(String a,String? b)=>b==null?const SizedBox.shrink():Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Text('$a: $b'));}
